    private func _parseScorePartMidiInstrument(_ element: XmlNode, _ trackInfo: TrackInfo) {
        let id: String = element.getAttribute("id", "")
        if !trackInfo.instruments.has(id) {
            return
        }
        let articulation: InstrumentArticulationWithPlaybackInfo = trackInfo.instruments.get(id)!
        for c in element.childElements() {
            switch c.localName! {
            case "midi-channel":
                articulation.outputMidiChannel = Number.parseInt(c.innerText, 10.0) - 1.0
            case "midi-bank":
                articulation.outputMidiBank = Number.parseInt(c.innerText, 10.0) - 1.0
            case "midi-program":
                articulation.outputMidiProgram = Number.parseInt(c.innerText, 10.0) - 1.0
            case "midi-unpitched":
                articulation.outputMidiNumber = Number.parseInt(c.innerText, 10.0) - 1.0
                articulation.isUnpitched = true
            case "volume":
                articulation.outputVolume = MusicXmlImporter._interpolatePercent(Number.parseFloat(c.innerText))
            case "pan":
                articulation.outputBalance = MusicXmlImporter._interpolatePan(Number.parseFloat(c.innerText))
            default:
                break
            }
        }
        articulation.id = PercussionMapper.tryMatchKnownArticulation(articulation)
        if articulation.id < 0 {
            articulation.id = 0.0
        }
    }

    private static func _interpolatePercent(_ value: Double) -> Double {
        return jsOr(MusicXmlImporter._interpolate(0.0, 100.0, 0.0, 16.0, value), 0)
    }

    private static func _interpolatePan(_ value: Double) -> Double {
        return jsOr(MusicXmlImporter._interpolate(-90.0, 90.0, 0.0, 16.0, value), 0)
    }

    private static func _interpolate(_ inputStart: Double, _ inputEnd: Double, _ outputStart: Double, _ outputEnd: Double, _ value: Double) -> Double {
        let t: Double = (value - inputStart) / (inputEnd - inputStart)
        return outputStart + (outputEnd - outputStart) * t
    }

