    private func _parsePartMeasure(_ element: XmlNode, _ masterBar: MasterBar, _ track: Track, _ implicit: Bool, _ isPartwise: Bool) {
        self._musicalPosition = 0.0
        self._lastBeat = nil
        let info: TrackInfo = self._indexToTrackInfo.get(track.index)!
        masterBar.alternateEndings = jsOr(masterBar.alternateEndings, info.openEndings)
        let barLines: List<XmlNode> = List<XmlNode>()
        for c in element.childElements() {
            switch c.localName! {
            case "note":
                self._parseNote(c, masterBar, track)
            case "backup":
                self._parseBackup(c)
            case "forward":
                self._parseForward(c)
            case "direction":
                self._parseDirection(c, masterBar, track)
            case "attributes":
                self._parseAttributes(c, masterBar, track)
            case "harmony":
                self._parseHarmony(c, track)
            case "print":
                self._parsePrint(c, masterBar, track, true)
            case "sound":
                self._parseSound(c, masterBar, track)
            case "barline":
                barLines.push(c)
            default:
                break
            }
        }
        for barLine in barLines {
            self._parseBarLine(barLine, masterBar, track)
        }
        let staff: Staff = self._getOrCreateStaff(track, 0.0)
        let bar: Bar = self._getOrCreateBar(staff, masterBar)
        if implicit {
            bar.barNumberDisplay = BarNumberDisplay.Hide
        } else if isPartwise {
            bar.barNumberDisplay = self._currentBarNumberDisplayBar ?? self._currentBarNumberDisplayPart
        } else {
            bar.barNumberDisplay = self._currentBarNumberDisplayPart ?? self._currentBarNumberDisplayBar
        }
        self._keyAllStaves = nil
    }

    private func _parsePrint(_ element: XmlNode, _ masterBar: MasterBar, _ track: Track?, _ isMeasurePrint: Bool) {
        if track != nil {
            if element.getAttribute("new-system", "no") == "yes" {
                track!.addLineBreaks(masterBar.index)
            } else if element.getAttribute("new-page", "no") == "yes" {
                track!.addLineBreaks(masterBar.index)
            }
        }
        var newDisplay: BarNumberDisplay? = nil
        for c in element.childElements() {
            switch c.localName! {
            case "measure-numbering":
                switch c.innerText {
                case "none":
                    newDisplay = BarNumberDisplay.Hide
                case "measure":
                    newDisplay = BarNumberDisplay.AllBars
                case "system":
                    newDisplay = BarNumberDisplay.FirstOfSystem
                default:
                    break
                }
            default:
                break
            }
        }
        if isMeasurePrint {
            self._currentBarNumberDisplayBar = newDisplay
        } else {
            self._currentBarNumberDisplayPart = newDisplay
        }
    }

    private func _parseBarLine(_ element: XmlNode, _ masterBar: MasterBar, _ track: Track) {
        for c in element.childElements() {
            switch c.localName! {
            case "bar-style":
                self._parseBarStyle(c, masterBar, track, element.getAttribute("location", "right"))
            case "ending":
                self._parseEnding(c, masterBar, track)
            case "repeat":
                self._parseRepeat(c, masterBar)
            default:
                break
            }
        }
    }

    private func _parseRepeat(_ element: XmlNode, _ masterBar: MasterBar) {
        let direction: String = element.getAttribute("direction")
        var times: Double = Number.parseInt(element.getAttribute("times"), 10.0)
        if times < 0 || Number.isNaN(times) {
            times = 2.0
        }
        if direction == "backward" {
            masterBar.repeatCount = times
        } else if direction == "forward" {
            masterBar.isRepeatStart = true
        }
    }

    private func _parseEnding(_ element: XmlNode, _ masterBar: MasterBar, _ track: Track) {
        let numbers: List<Double> = element.getAttribute("number").splitBy(",").map({ (v: String) -> Double in
            return Number.parseInt(v, 10.0)
        })
        var flags: Double = 0.0
        for num in numbers {
            flags = jsOr(flags, jsAnd(jsShl(1, num - 1.0), 255))
        }
        masterBar.alternateEndings = jsOr(masterBar.alternateEndings, flags)
        let info: TrackInfo = self._indexToTrackInfo.get(track.index)!
        switch element.getAttribute("type", "") {
        case "start":
            info.openEndings = jsOr(info.openEndings, flags)
        case "stop", "discontinue":
            info.openEndings = jsAnd(info.openEndings, jsNot(flags))
        default:
            break
        }
    }

    private func _parseBarStyle(_ element: XmlNode, _ masterBar: MasterBar, _ track: Track, _ location: String) {
        var style: BarLineStyle = BarLineStyle.Automatic
        switch element.innerText {
        case "dashed":
            style = BarLineStyle.Dashed
        case "dotted":
            style = BarLineStyle.Dotted
        case "heavy":
            style = BarLineStyle.Heavy
        case "heavy-heavy":
            style = BarLineStyle.HeavyHeavy
        case "heavy-light":
            style = BarLineStyle.HeavyLight
        case "light-heavy":
            style = BarLineStyle.LightHeavy
        case "light-light":
            style = BarLineStyle.LightLight
        case "none":
            style = BarLineStyle.None
        case "regular":
            style = BarLineStyle.Regular
        case "short":
            style = BarLineStyle.Short
        case "tick":
            style = BarLineStyle.Tick
        default:
            break
        }
        for s in track.staves {
            let bar: Bar = self._getOrCreateBar(s, masterBar)
            switch location {
            case "left":
                bar.barLineLeft = style
            case "right":
                bar.barLineRight = style
            default:
                break
            }
        }
    }

    private func _parseSound(_ element: XmlNode, _ masterBar: MasterBar, _ _track: Track) {
        for c in element.childElements() {
            switch c.localName! {
            case "midi-instrument":
                self._parseSoundMidiInstrument(c, masterBar)
            case "swing":
                self._parseSwing(c, masterBar)
            case "offset":
                break
            default:
                break
            }
        }
        self._parseSoundDirections(element, masterBar)
        if element.attributes.has("pan") {
            if !TypeHelper.isTruthy(self._nextBeatAutomations) {
                self._nextBeatAutomations = List<Automation>()
            }
            let automation: Automation = Automation()
            automation.type = AutomationType.Balance
            automation.value = MusicXmlImporter._interpolatePan(Number.parseFloat(element.attributes.get("pan")!))
            self._nextBeatAutomations!.push(automation)
        }
        if element.attributes.has("tempo") {
            if !TypeHelper.isTruthy(self._nextBeatAutomations) {
                self._nextBeatAutomations = List<Automation>()
            }
            let automation: Automation = Automation()
            automation.type = AutomationType.Tempo
            automation.value = MusicXmlImporter._interpolatePercent(Number.parseFloat(element.attributes.get("tempo")!))
            self._nextBeatAutomations!.push(automation)
        }
    }

    /**
     * Applies the jump and marker attributes of a `<sound>` (measure or direction level) as directions.
     */
    private func _parseSoundDirections(_ element: XmlNode, _ masterBar: MasterBar) -> Bool {
        var hasDirections: Bool = false
        if element.attributes.has("coda") {
            masterBar.addDirection(Direction.TargetCoda)
            hasDirections = true
        }
        if element.attributes.has("tocoda") {
            masterBar.addDirection(Direction.JumpDaCoda)
            hasDirections = true
        }
        if element.getAttribute("dacapo", "no") != "no" {
            masterBar.addDirection(Direction.JumpDaCapo)
            hasDirections = true
        }
        if element.attributes.has("dalsegno") {
            masterBar.addDirection(Direction.JumpDalSegno)
            hasDirections = true
        }
        if element.attributes.has("fine") {
            masterBar.addDirection(Direction.TargetFine)
            hasDirections = true
        }
        if element.attributes.has("segno") {
            masterBar.addDirection(Direction.TargetSegno)
            hasDirections = true
        }
        return hasDirections
    }

    /**
     * The texts (normalized via ) with which `<words>` print the directions
     * of the `<sound>` attributes. Such words are only the visual counterpart of the direction which renders its
     * own label, they are not added as additional beat text. Any other words next to a jump are kept as text.
     * Covers the default labels of the MuseScore export and the spelled-out forms, but no double segno/coda
     * or numbered forms as the directions are not mapped to their double variants.
     */
    nonisolated(unsafe) private static let _soundDirectionLabels: Map<String, List<String>> = Map<String, List<String>>([("dacapo", List<String>("dc", "dacapo", "dcalfine", "dacapoalfine", "dcalcoda", "dacapoalcoda")), ("dalsegno", List<String>("ds", "dalsegno", "delsegno", "dsalfine", "dalsegnoalfine", "delsegnoalfine", "dsalcoda", "dalsegnoalcoda", "delsegnoalcoda")), ("tocoda", List<String>("tocoda", "dacoda")), ("fine", List<String>("fine")), ("coda", List<String>("coda")), ("segno", List<String>("segno"))])

    /**
     * Lower-cases the text and removes dots and whitespace ("D. C. al Coda" -> "dcalcoda").
     */
    private static func _normalizeDirectionLabel(_ text: String) -> String {
        let lower: String = text.lowercase()
        var normalized: String = ""
        do {
            var i: Double = 0.0
            while i < lower.length {
                let c: String = lower.charAt(i)
                if c != "." && c != " " && c != "\t" && c != "\r" && c != "\n" && c != " " {
                    normalized += c
                }
                i += 1
            }
        }
        return normalized
    }

    private static func _isSoundDirectionLabel(_ words: String, _ sound: XmlNode) -> Bool {
        let normalized: String = MusicXmlImporter._normalizeDirectionLabel(words)
        for (attribute, labels) in MusicXmlImporter._soundDirectionLabels {
            if sound.attributes.has(attribute) && labels.indexOf(normalized) >= 0 {
                return true
            }
        }
        return false
    }

    private func _parseSwing(_ element: XmlNode, _ masterBar: MasterBar) {
        var first: Double = 0.0
        var second: Double = 0.0
        var swingType: Duration? = nil
        for c in element.childElements() {
            switch c.localName! {
            case "straight":
                masterBar.tripletFeel = TripletFeel.NoTripletFeel
                return
            case "first":
                first = Number.parseInt(c.innerText, 10.0)
            case "second":
                second = Number.parseInt(c.innerText, 10.0)
            case "swing-type":
                swingType = self._parseBeatDuration(c)
            default:
                break
            }
        }
        if !TypeHelper.isTruthy(swingType) {
            swingType = Duration.Eighth
        }
        if swingType! == Duration.Eighth {
            if first == 2.0 && second == 1.0 {
                masterBar.tripletFeel = TripletFeel.Triplet8th
            } else if first == 3.0 && second == 1.0 {
                masterBar.tripletFeel = TripletFeel.Dotted8th
            } else if first == 1.0 && second == 3.0 {
                masterBar.tripletFeel = TripletFeel.Scottish8th
            }
        } else if swingType! == Duration.Sixteenth {
            if first == 2.0 && second == 1.0 {
                masterBar.tripletFeel = TripletFeel.Triplet16th
            } else if first == 3.0 && second == 1.0 {
                masterBar.tripletFeel = TripletFeel.Dotted16th
            } else if first == 1.0 && second == 3.0 {
                masterBar.tripletFeel = TripletFeel.Scottish16th
            }
        }
    }

    private var _nextBeatAutomations: List<Automation>? = nil

    private var _nextBeatChord: Chord? = nil

    private var _nextBeatText: String? = nil

    /**
     * Where the pending beat text is written, it can be the label of a following line (e.g. music21).
     */
    private var _nextBeatTextTrackIndex: Double = -1.0

    private var _nextBeatTextBarIndex: Double = -1.0

    private var _nextBeatTextTicks: Double = -1.0

    /**
     * All beats in document order (see ).
     */
    private var _beats: List<Beat> = List<Beat>()

    /**
     * The placement of a span element at the current cursor.
     */
    private func _placement(_ masterBar: MasterBar, _ staffIndex: Double, _ voice: String, _ offset: Double) -> MusicXmlSpanPlacement {
        return MusicXmlSpanPlacement(staffIndex: staffIndex, voice: voice, position: MusicXmlSpanPosition(barIndex: masterBar.index, ticks: self._musicalPosition, offset: offset, sequence: self._beats.length))
    }

    private func _parseSoundMidiInstrument(_ element: XmlNode, _ _masterBar: MasterBar) {
        var automation: Automation
        for c in element.childElements() {
            switch c.localName! {
            case "midi-bank":
                if !TypeHelper.isTruthy(self._nextBeatAutomations) {
                    self._nextBeatAutomations = List<Automation>()
                }
                automation = Automation()
                automation.type = AutomationType.Bank
                automation.value = Number.parseInt(c.innerText, 10.0) - 1.0
                self._nextBeatAutomations!.push(automation)
            case "midi-program":
                if !TypeHelper.isTruthy(self._nextBeatAutomations) {
                    self._nextBeatAutomations = List<Automation>()
                }
                automation = Automation()
                automation.type = AutomationType.Instrument
                automation.value = Number.parseInt(c.innerText, 10.0) - 1.0
                self._nextBeatAutomations!.push(automation)
            case "volume":
                if !TypeHelper.isTruthy(self._nextBeatAutomations) {
                    self._nextBeatAutomations = List<Automation>()
                }
                automation = Automation()
                automation.type = AutomationType.Volume
                automation.value = MusicXmlImporter._interpolatePercent(Number.parseFloat(c.innerText))
                self._nextBeatAutomations!.push(automation)
            case "pan":
                if !TypeHelper.isTruthy(self._nextBeatAutomations) {
                    self._nextBeatAutomations = List<Automation>()
                }
                automation = Automation()
                automation.type = AutomationType.Balance
                automation.value = MusicXmlImporter._interpolatePan(Number.parseFloat(c.innerText))
                self._nextBeatAutomations!.push(automation)
            default:
                break
            }
        }
    }

    private func _parseHarmony(_ element: XmlNode, _ _track: Track) {
        let chord: Chord = Chord()
        var degreeParenthesis: Bool = false
        var degree: String = ""
        for childNode in element.childElements() {
            switch childNode.localName! {
            case "root":
                chord.name = self._parseHarmonyRoot(childNode)
            case "kind":
                chord.name = chord.name + self._parseHarmonyKind(childNode)
                if childNode.getAttribute("parentheses-degrees", "no") == "yes" {
                    degreeParenthesis = true
                }
            case "frame":
                self._parseHarmonyFrame(childNode, chord)
            case "degree":
                degree += self._parseDegree(childNode)
            default:
                break
            }
        }
        if TypeHelper.isTruthy(degree) {
            chord.name += degreeParenthesis ? "(\((degree).toTemplate()))" : degree
        }
        if element.getAttribute("print-frame", "no") == "yes" {
            chord.showDiagram = true
            self._score.stylesheet.globalDisplayChordDiagramsInScore = true
        }
        if element.getAttribute("print-object", "yes") == "yes" {
            chord.showDiagram = true
        }
        if self._nextBeatChord == nil {
            self._nextBeatChord = chord
        }
    }

    private func _parseDegree(_ element: XmlNode) -> String {
        var value: String = ""
        var alter: String = ""
        var type: String = ""
        for c in element.childElements() {
            switch c.localName! {
            case "degree-value":
                value = c.innerText
            case "degree-alter":
                switch c.innerText {
                case "-1":
                    alter = "♭"
                case "1":
                    alter = "♯"
                default:
                    break
                }
            case "degree-type":
                type += c.getAttribute("text", "")
            default:
                break
            }
        }
        return "\((type).toTemplate())\((alter).toTemplate())\((value).toTemplate())"
    }

    private func _parseHarmonyRoot(_ element: XmlNode) -> String {
        var rootStep: String = ""
        var rootAlter: String = ""
        for c in element.childElements() {
            switch c.localName! {
            case "root-step":
                rootStep = c.innerText
            case "root-alter":
                switch Number.parseFloat(c.innerText) {
                case -2.0:
                    rootAlter = "bb"
                case -1.0:
                    rootAlter = "b"
                case 0.0:
                    rootAlter = ""
                case 1.0:
                    rootAlter = "#"
                case 2.0:
                    rootAlter = "##"
                default:
                    break
                }
            default:
                break
            }
        }
        return rootStep + rootAlter
    }

    private func _parseHarmonyKind(_ xmlNode: XmlNode) -> String {
        let kindText: String = xmlNode.getAttribute("text")
        var resultKind: String = ""
        if TypeHelper.isTruthy(kindText) {
            resultKind = kindText
        } else {
            let kindContent: String = xmlNode.innerText
            switch kindContent {
            case "major":
                resultKind = ""
            case "minor":
                resultKind = "m"
            case "augmented":
                resultKind = "+"
            case "diminished":
                resultKind = "○"
            case "dominant":
                resultKind = "7"
            case "major-seventh":
                resultKind = "7M"
            case "minor-seventh":
                resultKind = "m7"
            case "diminished-seventh":
                resultKind = "○7"
            case "augmented-seventh":
                resultKind = "+7"
            case "half-diminished":
                resultKind = "⍉"
            case "major-minor":
                resultKind = "mMaj"
            case "major-sixth":
                resultKind = "maj6"
            case "minor-sixth":
                resultKind = "m6"
            case "dominant-ninth":
                resultKind = "9"
            case "major-ninth":
                resultKind = "maj9"
            case "minor-ninth":
                resultKind = "m9"
            case "dominant-11th":
                resultKind = "11"
            case "major-11th":
                resultKind = "maj11"
            case "minor-11th":
                resultKind = "m11"
            case "dominant-13th":
                resultKind = "13"
            case "major-13th":
                resultKind = "maj13"
            case "minor-13th":
                resultKind = "m13"
            case "suspended-second":
                resultKind = "sus2"
            case "suspended-fourth":
                resultKind = "sus4"
            case "Neapolitan":
                resultKind = "♭II"
            case "Italian":
                resultKind = "It⁺⁶"
            case "French":
                resultKind = "Fr⁺⁶"
            case "German":
                resultKind = "Fr⁺⁶"
            default:
                resultKind = kindContent
            }
        }
        return resultKind
    }

    private func _parseHarmonyFrame(_ xmlNode: XmlNode, _ chord: Chord) {
        for frameChild in xmlNode.childElements() {
            switch frameChild.localName! {
            case "frame-strings":
                let stringsCount: Double = Number.parseInt(frameChild.innerText, 10.0)
                chord.strings = List<Double>((stringsCount).toInt())
                do {
                    var i: Double = 0.0
                    while i < stringsCount {
                        chord.strings[(i).toInt()] = -1.0
                        i += 1
                    }
                }
            case "first-fret":
                chord.firstFret = Number.parseInt(frameChild.innerText, 10.0)
            case "frame-note":
                var stringNo: Double? = nil
                var fretNo: Double? = nil
                for noteChild in frameChild.childElements() {
                    switch noteChild.localName! {
                    case "string":
                        stringNo = Number.parseInt(noteChild.innerText, 10.0)
                    case "fret":
                        fretNo = Number.parseInt(noteChild.innerText, 10.0)
                        if TypeHelper.isTruthy(TypeHelper.isTruthy(stringNo) && fretNo! >= 0) {
                            chord.strings[(stringNo! - 1.0).toInt()] = fretNo!
                        }
                    case "barre":
                        if TypeHelper.isTruthy(TypeHelper.isTruthy(TypeHelper.isTruthy(stringNo) && TypeHelper.isTruthy(fretNo)) && noteChild.getAttribute("type") == "start") {
                            chord.barreFrets.push(fretNo!)
                        }
                    default:
                        break
                    }
                }
            default:
                break
            }
        }
    }

    private func _parseAttributes(_ element: XmlNode, _ masterBar: MasterBar, _ track: Track) {
        var staffIndex: Double
        var staff: Staff
        var bar: Bar
        if self._lastBeat == nil {
            for c in element.childElements() {
                switch c.localName! {
                case "divisions":
                    self._divisionsPerQuarterNote = Number.parseFloat(c.innerText)
                case "key":
                    self._parseKey(c, masterBar, track)
                case "time":
                    self._parseTime(c, masterBar)
                case "staves":
                    track.ensureStaveCount(Number.parseInt(c.innerText, 10.0))
                case "clef":
                    staffIndex = Number.parseInt(c.getAttribute("number", "1"), 10.0) - 1.0
                    staff = self._getOrCreateStaff(track, staffIndex)
                    bar = self._getOrCreateBar(staff, masterBar)
                    self._parseClef(c, bar)
                case "staff-details":
                    staffIndex = Number.parseInt(c.getAttribute("number", "1"), 10.0) - 1.0
                    staff = self._getOrCreateStaff(track, staffIndex)
                    self._parseStaffDetails(c, staff)
                case "transpose":
                    self._parseTranspose(c, track)
                case "measure-style":
                    self._parseMeasureStyle(c, masterBar, track, false)
                default:
                    break
                }
            }
        } else {
            for c in element.childElements() {
                switch c.localName! {
                case "divisions":
                    self._divisionsPerQuarterNote = Number.parseFloat(c.innerText)
                case "measure-style":
                    self._parseMeasureStyle(c, masterBar, track, true)
                default:
                    break
                }
            }
        }
    }

    private func _parseMeasureStyle(_ element: XmlNode, _ masterBar: MasterBar, _ track: Track, _ midBar: Bool) {
        let events: List<MusicXmlSpanEvent> = List<MusicXmlSpanEvent>()
        MusicXmlSpanReader.readMeasureStyle(element, midBar, events)
        if events.length > 0 {
            let staffIndex: Double = element.attributes.has("number") ? Number.parseInt(element.attributes.get("number")!, 10.0) - 1.0 : -1.0
            self._indexToTrackInfo.get(track.index)!.spans.process(events, self._placement(masterBar, staffIndex, "", 0.0))
        }
    }

    private func _parseTranspose(_ element: XmlNode, _ track: Track) {
        var semitones: Double = 0.0
        for c in element.childElements() {
            switch c.localName! {
            case "chromatic":
                semitones += Number.parseFloat(c.innerText)
            case "octave-change":
                semitones += Number.parseFloat(c.innerText) * 12.0
            default:
                break
            }
        }
        if element.attributes.has("number") {
            let staff: Staff = self._getOrCreateStaff(track, Number.parseInt(element.attributes.get("number")!, 10.0) - 1.0)
            self._getStaffContext(staff).transpose = semitones
            staff.displayTranspositionPitch = semitones
        } else {
            for staff in track.staves {
                self._getStaffContext(staff).transpose = semitones
                staff.displayTranspositionPitch = semitones
            }
        }
    }

    private func _parseStaffDetails(_ element: XmlNode, _ staff: Staff) {
        for c in element.childElements() {
            switch c.localName! {
            case "staff-lines":
                staff.standardNotationLineCount = Number.parseInt(c.innerText, 10.0)
            case "staff-tuning":
                self._parseStaffTuning(c, staff)
            case "capo":
                staff.capo = Number.parseInt(c.innerText, 10.0)
            default:
                break
            }
        }
    }

    private func _parseStaffTuning(_ element: XmlNode, _ staff: Staff) {
        if staff.stringTuning.tunings.length == 0.0 {
            staff.showTablature = true
            staff.showStandardNotation = false
            staff.stringTuning.tunings = List<Double>((staff.standardNotationLineCount).toInt()).fill(0.0)
        }
        let line: Double = Number.parseInt(element.getAttribute("line"), 10.0)
        var tuningStep: String = "C"
        var tuningOctave: String = ""
        var tuningAlter: Double = 0.0
        for c in element.childElements() {
            switch c.localName! {
            case "tuning-step":
                tuningStep = c.innerText
            case "tuning-alter":
                tuningAlter = Number.parseFloat(c.innerText)
            case "tuning-octave":
                tuningOctave = c.innerText
            default:
                break
            }
        }
        let tuning: Double = ModelUtils.getTuningForText(tuningStep + tuningOctave) + tuningAlter
        staff.tuning[(staff.tuning.length - line).toInt()] = tuning
    }

    private func _parseClef(_ element: XmlNode, _ bar: Bar) {
        var sign: String = "s"
        var line: Double = 0.0
        for c in element.childElements() {
            switch c.localName! {
            case "sign":
                sign = c.innerText.lowercase()
            case "line":
                line = Number.parseInt(c.innerText, 10.0)
            case "clef-octave-change":
                switch Number.parseInt(c.innerText, 10.0) {
                case -2.0:
                    bar.clefOttava = Ottavia._15mb
                case -1.0:
                    bar.clefOttava = Ottavia._8vb
                case 1.0:
                    bar.clefOttava = Ottavia._8va
                case 2.0:
                    bar.clefOttava = Ottavia._15mb
                default:
                    break
                }
            default:
                break
            }
        }
        switch sign {
        case "g":
            bar.clef = Clef.G2
        case "f":
            bar.clef = Clef.F4
        case "c":
            if line == 3.0 {
                bar.clef = Clef.C3
            } else {
                bar.clef = Clef.C4
            }
        case "percussion":
            bar.clef = Clef.Neutral
            if bar.index == 0.0 {
                bar.staff.isPercussion = true
                bar.staff.showTablature = false
            }
        case "tab":
            bar.clef = Clef.G2
            bar.staff.showTablature = true
        default:
            bar.clef = Clef.G2
        }
    }

    private func _parseTime(_ element: XmlNode, _ masterBar: MasterBar) {
        var beatsParsed: Bool = false
        var beatTypeParsed: Bool = false
        for c in element.childElements() {
            let v: String = c.innerText
            switch c.localName! {
            case "beats":
                if !beatsParsed {
                    if v.indexOfInDouble("+") == -1.0 {
                        masterBar.timeSignatureNumerator = Number.parseInt(v, 10.0)
                    } else {
                        masterBar.timeSignatureNumerator = v.splitBy("+").map({ (v: String) -> Double in
                            return Number.parseInt(v, 10.0)
                        }).reduce({ (sum: Double, v: Double) -> Double in
                            return v + sum
                        }, 0.0)
                    }
                    beatsParsed = true
                }
            case "beat-type":
                if !beatTypeParsed {
                    if v.indexOfInDouble("+") == -1.0 {
                        masterBar.timeSignatureDenominator = Number.parseInt(v, 10.0)
                    } else {
                        masterBar.timeSignatureDenominator = v.splitBy("+").map({ (v: String) -> Double in
                            return Number.parseInt(v, 10.0)
                        }).reduce({ (sum: Double, v: Double) -> Double in
                            return v + sum
                        }, 0.0)
                    }
                    beatTypeParsed = true
                }
            default:
                break
            }
        }
        switch element.getAttribute("symbol", "") {
        case "common", "cut":
            masterBar.timeSignatureCommon = true
        default:
            break
        }
    }

    private var _keyAllStaves: (KeySignature, KeySignatureType)? = nil

    private func _parseKey(_ element: XmlNode, _ masterBar: MasterBar, _ track: Track) {
        var fifths: Double = -(Double(KeySignature.C.rawValue))
        var mode: String = ""
        for c in element.childElements() {
            switch c.localName! {
            case "fifths":
                fifths = Number.parseInt(c.innerText, 10.0)
            case "mode":
                mode = c.innerText
            default:
                break
            }
        }
        var keySignature: KeySignature
        if -7.0 <= fifths && fifths <= 7 {
            keySignature = KeySignature.fromValue(fifths)
        } else {
            keySignature = KeySignature.C
        }
        var keySignatureType: KeySignatureType
        if mode == "minor" {
            keySignatureType = KeySignatureType.Minor
        } else {
            keySignatureType = KeySignatureType.Major
        }
        if element.attributes.has("number") {
            let staff: Staff = self._getOrCreateStaff(track, Number.parseInt(element.attributes.get("number")!, 10.0) - 1.0)
            let bar: Bar = self._getOrCreateBar(staff, masterBar)
            bar.keySignature = keySignature
            bar.keySignatureType = keySignatureType
        } else {
            self._keyAllStaves = (keySignature, keySignatureType)
            for s in track.staves {
                if s.bars.length > masterBar.index {
                    s.bars[(masterBar.index).toInt()].keySignature = keySignature
                    s.bars[(masterBar.index).toInt()].keySignatureType = keySignatureType
                }
            }
        }
    }

    private func _parseDirection(_ element: XmlNode, _ masterBar: MasterBar, _ track: Track) {
        let directionTypes: List<XmlNode> = List<XmlNode>()
        var offset: Double? = nil
        var offsetAffectsSound: Bool = false
        var voice: String = ""
        var staffIndex: Double = -1.0
        var tempo: Double = -1.0
        var sound: XmlNode? = nil
        var hasSoundDirections: Bool = false
        var allWords: String = ""
        for c in element.childElements() {
            switch c.localName! {
            case "direction-type":
                let types: List<XmlNode> = c.childElements()
                if types.length > 0 {
                    directionTypes.push(types[(types.length - 1.0).toInt()])
                }
                for t in types {
                    if t.localName == "words" {
                        allWords += t.innerText
                    }
                }
            case "offset":
                offset = Number.parseFloat(c.innerText)
                offsetAffectsSound = c.getAttribute("sound", "no") == "yes"
            case "voice":
                voice = c.innerText.trim()
            case "staff":
                staffIndex = Number.parseInt(c.innerText, 10.0) - 1.0
            case "sound":
                if c.attributes.has("tempo") {
                    tempo = Number.parseFloat(c.attributes.get("tempo")!)
                }
                sound = c
                hasSoundDirections = self._parseSoundDirections(c, masterBar)
            default:
                break
            }
        }
        var staff: Staff
        if staffIndex >= 0 {
            staff = self._getOrCreateStaff(track, staffIndex)
        } else if self._lastBeat != nil {
            staff = self._lastBeat!.voice.bar.staff
        } else {
            staff = self._getOrCreateStaff(track, 0.0)
        }
        self._getOrCreateBar(staff, masterBar)
        let offsetTicks: Double = offset != nil ? self._musicXmlDivisionsToAlphaTabTicks(offset!) : 0.0
        let totalDuration: Double = masterBar.calculateDuration(false)
        let displayRatioPosition: Double = (self._musicalPosition + offsetTicks) / totalDuration
        let soundRatioPosition: Double = offsetAffectsSound ? displayRatioPosition : self._musicalPosition / totalDuration
        if tempo > 0 {
            let tempoAutomation: Automation = Automation()
            tempoAutomation.type = AutomationType.Tempo
            tempoAutomation.value = tempo
            tempoAutomation.ratioPosition = soundRatioPosition
            if !self._hasSameTempo(masterBar, tempoAutomation) {
                masterBar.tempoAutomations.push(tempoAutomation)
            }
        }
        var previousWords: String = ""
        let spanEvents: List<MusicXmlSpanEvent> = List<MusicXmlSpanEvent>()
        let pedalEvents: List<MusicXmlSpanEvent> = List<MusicXmlSpanEvent>()
        for direction in directionTypes {
            switch direction.localName! {
            case "rehearsal":
                masterBar.section = Section()
                masterBar.section!.marker = direction.innerText
            case "segno":
                if !hasSoundDirections {
                    masterBar.addDirection(Direction.TargetSegno)
                }
            case "coda":
                if !hasSoundDirections {
                    masterBar.addDirection(Direction.TargetCoda)
                }
            case "words":
                previousWords = direction.innerText
            case "wedge":
                MusicXmlSpanReader.readWedge(direction, spanEvents)
            case "dynamics":
                let newDynamics: DynamicValue? = self._parseDynamics(direction)
                if newDynamics != nil {
                    self._currentDynamics = (newDynamics as! DynamicValue)
                    self._score.stylesheet.hideDynamics = false
                }
            case "dashes", "bracket":
                if self._parseLine(direction, previousWords, track, masterBar.index, spanEvents) {
                    previousWords = ""
                }
            case "pedal":
                MusicXmlSpanReader.readPedal(direction, pedalEvents)
            case "metronome":
                if tempo <= 0 {
                    self._parseMetronome(direction, masterBar, displayRatioPosition)
                }
            case "octave-shift":
                MusicXmlSpanReader.readOctaveShift(direction, spanEvents)
            default:
                break
            }
        }
        let spans: MusicXmlSpanTracker = self._indexToTrackInfo.get(track.index)!.spans
        if spanEvents.length > 0 {
            spans.process(spanEvents, self._placement(masterBar, staffIndex, voice, offsetTicks))
        }
        if pedalEvents.length > 0 {
            spans.process(pedalEvents, self._placement(masterBar, staff.index, voice, offsetTicks))
        }
        if TypeHelper.isTruthy(TypeHelper.isTruthy(previousWords) && !(hasSoundDirections && MusicXmlImporter._isSoundDirectionLabel(allWords, sound!))) {
            self._nextBeatText = previousWords
            self._nextBeatTextTrackIndex = track.index
            self._nextBeatTextBarIndex = masterBar.index
            self._nextBeatTextTicks = self._musicalPosition
        }
    }

    /**
     * Reads a `<dashes>` or `<bracket>` line.
     */
    private func _parseLine(_ element: XmlNode, _ words: String, _ track: Track, _ barIndex: Double, _ spanEvents: List<MusicXmlSpanEvent>) -> Bool {
        let usesPendingText: Bool = words.length == 0.0 && self._nextBeatText != nil && self._nextBeatTextTrackIndex == track.index && self._nextBeatTextBarIndex == barIndex && self._nextBeatTextTicks == self._musicalPosition && element.getAttribute("type", "start") == "start"
        let label: String = usesPendingText ? self._nextBeatText! : words
        if MusicXmlSpanReader.lineKind(label) == MusicXmlSpanKind.None {
            MusicXmlSpanReader.readLine(element, "", spanEvents)
            return false
        }
        MusicXmlSpanReader.readLine(element, label, spanEvents)
        if usesPendingText {
            self._nextBeatText = nil
        }
        return true
    }

    private func _parseMetronome(_ element: XmlNode, _ masterBar: MasterBar, _ ratioPosition: Double) {
        var unit: Duration? = nil
        var dots: Double = 0.0
        var perMinute: Double = -1.0
        for c in element.childElements() {
            switch c.localName! {
            case "beat-unit":
                unit = self._parseBeatDuration(c)
            case "beat-unit-dot":
                dots += 1
            case "per-minute":
                perMinute = Number.parseFloat(c.innerText)
            default:
                break
            }
        }
        if unit != nil && perMinute > 0 {
            let tempoAutomation: Automation = Automation()
            tempoAutomation.type = AutomationType.Tempo
            let quartersPerUnit: Double = (MidiUtils.toTicks(unit!) / MidiUtils.QuarterTime) * (2.0 - Math.pow(0.5, dots))
            tempoAutomation.value = perMinute * quartersPerUnit
            tempoAutomation.ratioPosition = ratioPosition
            if !self._hasSameTempo(masterBar, tempoAutomation) {
                masterBar.tempoAutomations.push(tempoAutomation)
            }
        }
    }

    private func _hasSameTempo(_ masterBar: MasterBar, _ tempoAutomation: Automation) -> Bool {
        for existing in masterBar.tempoAutomations {
            if tempoAutomation.ratioPosition == existing.ratioPosition && tempoAutomation.value == existing.value {
                return true
            }
        }
        return false
    }

    private func _parseDynamics(_ element: XmlNode) -> DynamicValue? {
        for c in element.childElements() {
            let dynamicString: String = c.localName.uppercase()
            switch dynamicString {
            case "PPP", "PP", "P", "MP", "MF", "F", "FF", "FFF", "PPPP", "PPPPP", "PPPPPP", "FFFF", "FFFFF", "FFFFFF", "SF", "SFP", "SFPP", "FP", "RF", "RFZ", "SFZ", "SFFZ", "FZ", "N", "PF", "SFZP":
                return TypeHelper.parseEnum(dynamicString, DynamicValue.self)
            default:
                break
            }
        }
        return nil
    }

    private func _parseForward(_ element: XmlNode) {
        for c in element.childElements() {
            switch c.localName! {
            case "duration":
                self._musicalPosition += self._musicXmlDivisionsToAlphaTabTicks(Number.parseFloat(c.innerText))
            default:
                break
            }
        }
    }

    private func _parseBackup(_ element: XmlNode) {
        for c in element.childElements() {
            switch c.localName! {
            case "duration":
                let beat: Beat? = self._lastBeat
                if TypeHelper.isTruthy(beat) {
                    var musicalPosition: Double = self._musicalPosition
                    musicalPosition -= self._musicXmlDivisionsToAlphaTabTicks(Number.parseFloat(c.innerText))
                    if musicalPosition < 0 {
                        musicalPosition = 0.0
                    }
                    self._musicalPosition = musicalPosition
                }
            default:
                break
            }
        }
    }

    private func _getOrCreateStaff(_ track: Track, _ staffIndex: Double) -> Staff {
        while track.staves.length <= staffIndex {
            let staff: Staff = Staff()
            track.addStaff(staff)
            if self._score.masterBars.length > 0 {
                self._getOrCreateBar(staff, self._score.masterBars[(self._score.masterBars.length - 1.0).toInt()])
            }
        }
        return track.staves[(staffIndex).toInt()]
    }

    private func _getOrCreateBar(_ staff: Staff, _ masterBar: MasterBar) -> Bar {
        let voiceCount: Double = staff.bars.length == 0.0 ? 1.0 : staff.bars[0].voices.length
        while staff.bars.length <= masterBar.index {
            let newBar: Bar = Bar()
            staff.addBar(newBar)
            if TypeHelper.isTruthy(newBar.previousBar) {
                newBar.clef = newBar.previousBar!.clef
                newBar.clefOttava = newBar.previousBar!.clefOttava
                newBar.keySignature = newBar.previousBar!.keySignature
                newBar.keySignatureType = newBar.previousBar!.keySignatureType
            }
            if self._keyAllStaves != nil {
                newBar.keySignature = self._keyAllStaves!.0
                newBar.keySignatureType = self._keyAllStaves!.1
            }
            do {
                var i: Double = 0.0
                while i < voiceCount {
                    let voice: Voice = Voice()
                    newBar.addVoice(voice)
                    i += 1
                }
            }
        }
        return staff.bars[(masterBar.index).toInt()]
    }

    private func _resolveAndPlaceVoice(_ staff: Staff, _ rawVoice: String, _ bar: Bar) -> Voice {
        var packing: StaffVoicePacking
        if self._staffVoicePacking.has(staff) {
            packing = self._staffVoicePacking.get(staff)!
        } else {
            packing = StaffVoicePacking()
            self._staffVoicePacking.set(staff, packing)
        }
        if packing.mapping.has(rawVoice) {
            return bar.voices[(packing.mapping.get(rawVoice)!).toInt()]
        }
        var newVoiceNumber: Double = Number.parseInt(rawVoice, 10.0)
        if Number.isNaN(newVoiceNumber) {
            Logger.warning("MusicXML", "Voices need to be specified as numbers")
            newVoiceNumber = 0.0
        }
        if packing.sortedRawVoices.length == 0.0 {
            packing.sortedRawVoices.push(rawVoice)
            packing.mapping.set(rawVoice, 0.0)
            return bar.voices[0]
        }
        var insertPos: Double = packing.sortedRawVoices.length
        do {
            var i: Double = 0.0
            while i < packing.sortedRawVoices.length {
                let existing: Double = Number.parseInt(packing.sortedRawVoices[(i).toInt()], 10.0)
                let existingNumber: Double = Number.isNaN(existing) ? 0.0 : existing
                if existingNumber > newVoiceNumber {
                    insertPos = i
                    break
                }
                i += 1
            }
        }
        packing.sortedRawVoices.splice(insertPos, 0.0, rawVoice)
        for b in staff.bars {
            b.voices.splice(insertPos, 0.0, Voice())
            do {
                var i: Double = insertPos
                while i < b.voices.length {
                    b.voices[(i).toInt()].index = i
                    b.voices[(i).toInt()].bar = b
                    i += 1
                }
            }
        }
        packing.mapping.clear()
        do {
            var i: Double = 0.0
            while i < packing.sortedRawVoices.length {
                packing.mapping.set(packing.sortedRawVoices[(i).toInt()], i)
                i += 1
            }
        }
        return bar.voices[(insertPos).toInt()]
    }

    private func _parseNote(_ element: XmlNode, _ masterBar: MasterBar, _ track: Track) {
        var isChord: Bool = false
        var note: Note? = nil
        var isPitched: Bool = false
        var instrumentId: String? = nil
        var staffIndex: Double = 0.0
        var voiceRaw: String = "1"
        var isPlacementComplete: Bool = false
        for c in element.childElements() {
            switch c.localName! {
            case "cue":
                return
            case "chord":
                isChord = true
            case "pitch":
                note = self._parsePitch(c)
                isPitched = true
            case "unpitched":
                note = self._parseUnpitched(c, track)
            case "instrument":
                instrumentId = c.getAttribute("id", "")
            case "voice":
                let trimmed: String = c.innerText.trim()
                voiceRaw = trimmed.length > 0 ? trimmed : "1"
            case "staff":
                staffIndex = Number.parseInt(c.innerText, 10.0) - 1.0
                isPlacementComplete = true
            case "beam", "notations", "lyric", "play", "listen":
                isPlacementComplete = true
            default:
                break
            }
            if isPlacementComplete {
                break
            }
        }
        if isChord && !TypeHelper.isTruthy(self._lastBeat) {
            Logger.warning("MusicXML", "Malformed MusicXML, <chord /> cannot be set on the first note of a measure")
            isChord = false
        }
        if isChord && !TypeHelper.isTruthy(note) {
            Logger.warning("MusicXML", "Cannot mix <chord /> and <rest />")
            isChord = false
        }
        let harmonic: MusicXmlHarmonic? = note != nil ? MusicXmlImporter._readHarmonic(element) : nil
        if isChord && harmonic != nil && self._foldHarmonicNote(note!, harmonic!, track, staffIndex) {
            return
        }
        let writtenNoteValue: Double = note != nil ? self._calculatePitchedNoteValue(note!) : 0.0
        let staff: Staff = self._getOrCreateStaff(track, staffIndex)
        var beat: Beat
        if isChord {
            beat = self._lastBeat!
            beat.addNote(note!)
        } else {
            beat = self._createBeat(staff, masterBar, voiceRaw, note)
        }
        if note != nil {
            note!.isVisible = element.getAttribute("print-object", "yes") != "no"
            self._resolveAttachedNote(note!, instrumentId, isPitched)
            if harmonic != nil && harmonic!.pitch != MusicXmlHarmonicPitch.None {
                self._harmonicGroups.set(harmonic!.group, MusicXmlHarmonicGroup(note: note!, type: harmonic!.type, isBasePitch: harmonic!.pitch == MusicXmlHarmonicPitch.Base, hasTouchingPitch: false))
            }
        }
        var graceType: GraceType = GraceType.None
        var graceDurationInDivisions: Double = 0.0
        var beamMode: BeatBeamingMode? = nil
        var durationInTicks: Double = -1.0
        var beatDuration: Duration? = nil
        var dots: Double = 0.0
        var tupletNumerator: Double = -1.0
        var tupletDenominator: Double = -1.0
        var preferredBeamDirection: BeamDirection? = nil
        for c in element.childElements() {
            switch c.localName! {
            case "grace":
                let makeTime: Double = Number.parseFloat(c.getAttribute("make-time", "-1"))
                if makeTime >= 0 {
                    graceDurationInDivisions = self._musicXmlDivisionsToAlphaTabTicks(makeTime)
                    graceType = GraceType.BeforeBeat
                } else {
                    graceType = GraceType.OnBeat
                }
                if c.getAttribute("slash") == "yes" {
                    graceType = GraceType.BeforeBeat
                }
            case "rest":
                if beatDuration == nil {
                    beatDuration = Duration.Whole
                }
            case "duration":
                durationInTicks = self._parseDuration(c)
            case "tied":
                if TypeHelper.isTruthy(note) {
                    self._parseTied(c, note!, voiceRaw)
                }
            case "type":
                beatDuration = self._parseBeatDuration(c)
            case "dot":
                dots += 1
            case "accidental":
                if note == nil {
                    Logger.warning("MusicXML", "Malformed MusicXML, missing pitch or unpitched for note")
                } else {
                    self._parseAccidental(c, note!)
                }
            case "time-modification":
                for tmc in c.childElements() {
                    switch tmc.localName! {
                    case "actual-notes":
                        tupletNumerator = Number.parseInt(tmc.innerText, 10.0)
                    case "normal-notes":
                        tupletDenominator = Number.parseInt(tmc.innerText, 10.0)
                    default:
                        break
                    }
                }
            case "stem":
                preferredBeamDirection = self._parseStem(c)
            case "notehead":
                if note == nil {
                    Logger.warning("MusicXML", "Malformed MusicXML, missing pitch or unpitched for note")
                } else {
                    self._parseNoteHead(c, note!, beatDuration ?? Duration.Quarter, preferredBeamDirection ?? self._estimateBeamDirection(writtenNoteValue))
                }
            case "beam":
                if c.getAttribute("number", "1") == "1" {
                    switch c.innerText {
                    case "begin":
                        beamMode = BeatBeamingMode.ForceMergeWithNext
                    case "continue":
                        beamMode = BeatBeamingMode.ForceMergeWithNext
                    case "end":
                        beamMode = BeatBeamingMode.ForceSplitToNext
                    default:
                        break
                    }
                }
            case "notations":
                self._parseNotations(c, note, beat, voiceRaw)
            case "lyric":
                self._parseLyric(c, beat, track)
            case "play":
                self._parsePlay(c, note)
            default:
                break
            }
        }
        if !isChord {
            if beamMode == nil {
                beat.beamingMode = self._getStaffContext(staff).isExplicitlyBeamed ? BeatBeamingMode.ForceSplitToNext : BeatBeamingMode.Auto
            } else {
                beat.beamingMode = beamMode!
                self._getStaffContext(staff).isExplicitlyBeamed = true
            }
            if durationInTicks < 0 && beatDuration != nil {
                durationInTicks = MidiUtils.toTicks(beatDuration!)
                if dots > 0 {
                    durationInTicks = MidiUtils.applyDot(durationInTicks, dots == 2.0)
                }
            }
            if graceType != GraceType.None {
                beat.graceType = graceType
                self._applyBeatDurationFromTicks(beat, graceDurationInDivisions, nil, false)
            } else {
                beat.tupletNumerator = tupletNumerator
                beat.tupletDenominator = tupletDenominator
                beat.dots = dots
                beat.preferredBeamDirection = preferredBeamDirection
                self._applyBeatDurationFromTicks(beat, durationInTicks, beatDuration, true)
            }
            self._musicalPosition = beat.displayEnd
            self._lastBeat = beat
        }
        if note != nil {
            self._finalizeStringNumber(note!)
            if harmonic != nil && harmonic!.type == HarmonicType.Natural && (!note!.isStringed || ModelUtils.harmonicValueToPitch(note!.fret) > 0) {
                note!.harmonicType = HarmonicType.Natural
                note!.harmonicValue = ModelUtils.deltaFretToHarmonicValue(note!.fret)
            }
        }
    }

    /**
     * Reads the `<technical><harmonic>` of the note.
     * A harmonic without `<natural/>` or `<artificial/>` only shows the harmonic circle, like Guitar Pro 8 we ignore it
     * (it exports pinch, tap and semi harmonics like this).
     */
    private static func _readHarmonic(_ element: XmlNode) -> MusicXmlHarmonic? {
        for notations in element.childElements() {
            if notations.localName != "notations" {
                continue
            }
            for technical in notations.childElements() {
                if technical.localName != "technical" {
                    continue
                }
                for c in technical.childElements() {
                    if c.localName != "harmonic" {
                        continue
                    }
                    let harmonic: MusicXmlHarmonic = MusicXmlHarmonic(type: HarmonicType.None, pitch: MusicXmlHarmonicPitch.None, group: c.getAttribute("number", "1"))
                    for h in c.childElements() {
                        switch h.localName! {
                        case "natural":
                            harmonic.type = HarmonicType.Natural
                        case "artificial":
                            harmonic.type = HarmonicType.Artificial
                        case "base-pitch":
                            harmonic.pitch = MusicXmlHarmonicPitch.Base
                        case "touching-pitch":
                            harmonic.pitch = MusicXmlHarmonicPitch.Touching
                        case "sounding-pitch":
                            harmonic.pitch = MusicXmlHarmonicPitch.Sounding
                        default:
                            break
                        }
                    }
                    return harmonic.type != HarmonicType.None ? harmonic : nil
                }
            }
        }
        return nil
    }

    /**
     * MusicXML writes a harmonic as separate chord notes for the base pitch (the played note),
     * the touching pitch (where the string is touched) and the sounding pitch (what is heard).
     * In alphaTab a harmonic is one note: the touching and sounding notes are folded into the note
     * of their harmonic (which they follow in all known files: the MusicXML examples, the LilyPond test suite, Guitar Pro 8)
     * and only define its harmonic value. A base pitch note starts a new harmonic.
     * The touching pitch defines the harmonic more precisely than the sounding pitch (e.g. fret 7 and 19 sound the same),
     * Guitar Pro 8 writes both consistently.
     * The pitch is relative to the staff the note specifies, Guitar Pro 8 omits the `<staff>` on these chord notes
     * of a tablature staff and writes them in the pitch of the first staff.
     */
    private func _foldHarmonicNote(_ note: Note, _ harmonic: MusicXmlHarmonic, _ track: Track, _ staffIndex: Double) -> Bool {
        let group: MusicXmlHarmonicGroup? = self._harmonicGroups.get(harmonic.group)
        if group == nil || harmonic.pitch == MusicXmlHarmonicPitch.Base || harmonic.pitch == MusicXmlHarmonicPitch.None {
            return false
        }
        let played: Note = group!.note
        if group!.isBasePitch && !group!.hasTouchingPitch {
            let transpose: Double = self._getStaffContext(self._getOrCreateStaff(track, staffIndex)).transpose
            var interval: Double = self._calculatePitchedNoteValue(note) + transpose - self._calculatePitchedNoteValue(played)
            if played.isStringed && group!.type == HarmonicType.Natural {
                interval += played.fret
            }
            if harmonic.pitch == MusicXmlHarmonicPitch.Touching {
                played.harmonicType = group!.type
                played.harmonicValue = ModelUtils.deltaFretToHarmonicValue(interval)
                group!.hasTouchingPitch = true
            } else {
                do {
                    var fret: Double = 1.0
                    while fret <= 24 {
                        let value: Double = ModelUtils.deltaFretToHarmonicValue(fret)
                        if ModelUtils.harmonicValueToPitch(value) == interval {
                            played.harmonicType = group!.type
                            played.harmonicValue = value
                            break
                        }
                        fret += 1
                    }
                }
            }
        }
        return true
    }

    /**
     * Creates a new beat for the note on the given staff and inserts it into the voice at the current musical position.
     * The beat level information of the note (beaming, duration, tuplets etc.) is applied after the note was fully parsed.
     */
    private func _createBeat(_ staff: Staff, _ masterBar: MasterBar, _ voiceRaw: String, _ note: Note?) -> Beat {
        let bar: Bar = self._getOrCreateBar(staff, masterBar)
        let voice: Voice = self._resolveAndPlaceVoice(staff, voiceRaw, bar)
        let actualMusicalPosition: Double = voice.beats.length == 0.0 ? 0.0 : voice.beats[(voice.beats.length - 1.0).toInt()].displayEnd
        var gap: Double = self._musicalPosition - actualMusicalPosition
        if gap > 0 {
            if TypeHelper.isTruthy(TypeHelper.isTruthy(TypeHelper.isTruthy(TypeHelper.isTruthy(TypeHelper.isTruthy(self._lastBeat) && self._lastBeat!.beamingMode == BeatBeamingMode.ForceMergeWithNext) && self._lastBeat!.voice.bar.staff.index != staff.index) && voice.beats.length > 0) && voice.beats[(voice.beats.length - 1.0).toInt()].beamingMode == BeatBeamingMode.ForceMergeWithNext) {
                let preferredDuration: Duration = voice.beats[(voice.beats.length - 1.0).toInt()].duration
                while gap > 0 {
                    let restGap: Beat? = self._createRestForGap(gap, preferredDuration)
                    if restGap != nil {
                        self._insertBeatToVoice(restGap!, voice)
                        gap -= restGap!.playbackDuration
                    } else {
                        break
                    }
                }
            }
            if gap > 0 {
                let placeholder: Beat = Beat()
                placeholder.dynamics = self._currentDynamics
                placeholder.isEmpty = true
                placeholder.duration = Duration.TwoHundredFiftySixth
                placeholder.overrideDisplayDuration = gap
                placeholder.updateDurations()
                self._insertBeatToVoice(placeholder, voice)
            }
        } else if gap < 0 {
            Logger.error("MusicXML", "Unsupported forward/backup detected. Cannot fill new beats into already filled area of voice")
        }
        let newBeat: Beat = Beat()
        self._beats.push(newBeat)
        self._harmonicGroups.clear()
        newBeat.isEmpty = false
        newBeat.dynamics = self._currentDynamics
        let automations: List<Automation>? = self._nextBeatAutomations
        self._nextBeatAutomations = nil
        if automations != nil {
            for automation in automations! {
                newBeat.automations.push(automation)
            }
        }
        let chord: Chord? = self._nextBeatChord
        self._nextBeatChord = nil
        if chord != nil {
            newBeat.chordId = chord!.uniqueId
            if !voice.bar.staff.hasChord(chord!.uniqueId) {
                voice.bar.staff.addChord(newBeat.chordId!, chord!)
            }
        }
        if TypeHelper.isTruthy(self._nextBeatText) {
            newBeat.text = self._nextBeatText!
            self._nextBeatText = nil
        }
        if note != nil {
            newBeat.addNote(note!)
        }
        self._insertBeatToVoice(newBeat, voice)
        return newBeat
    }

    /**
     * Validates the string parsed from `<technical><string>` and decides whether it is a
     * tab position (string + fret) or a string number annotation on a pitched note.
     */
    private func _finalizeStringNumber(_ note: Note) {
        if Number.isNaN(note.string) {
            return
        }
        let stringCount: Double = Note.getStringCount(note.beat.voice.bar.staff)
        if note.string < 1 || note.string > stringCount {
            Logger.warning("MusicXML", "Ignoring <string> outside of the available \((stringCount).toTemplate()) strings")
            note.string = Number.NaN
            note.fret = Number.NaN
            return
        }
        note.beat.noteStringLookup.set(note.string, note)
        if !note.isStringed && note.isDead && note.beat.voice.bar.staff.tuning.length > 0 {
            note.fret = Math.max(0.0, self._calculatePitchedNoteValue(note) - note.stringTuning)
        }
        if !note.isStringed && !note.isPercussion {
            note.showStringNumber = true
        }
    }

    /**
     * Whether the note is played on a fretted instrument, which decides whether an x notehead or a mute is a dead note.
     * MusicXML has no dedicated element for dead notes. Applications encode them as x notehead (MuseScore, TuxGuitar, Guitar Pro)
     * or mute (TuxGuitar, Guitar Pro) which have other meanings on other instruments (e.g. hi-hats on percussion, spoken notes).
     * The whole part is checked as the tuning is often only specified on the tablature staff while the x notehead
     * is on the standard notation staff.
     */
    private func _isFrettedInstrumentNote(_ note: Note) -> Bool {
        if note.isPercussion {
            return false
        }
        for staff in note.beat.voice.bar.staff.track.staves {
            if staff.isStringed {
                return true
            }
        }
        return false
    }

    /**
     * Resolves the note values which depend on the staff the note is attached to.
     *
     * Purpose:
     * - Apply the staff transposition to pitched notes.
     * - Resolve percussion articulation consistently in one place.
     *
     * Why this is called right after attaching the note:
     * - The logic relies on the note context (attached beat/voice/bar/staff), especially
     *   staff percussion state, and on the final display value after transposition.
     * - The remaining children of the note are interpreted afterwards and rely on the resolved
     *   note (e.g. ties are matched on the transposed pitch).
     */
    private func _resolveAttachedNote(_ note: Note, _ instrumentId: String?, _ isPitched: Bool) {
        let staff: Staff = note.beat.voice.bar.staff
        if isPitched {
            let transpose: Double = self._getStaffContext(staff).transpose
            if transpose != 0.0 {
                let value: Double = note.octave * 12.0 + note.tone + transpose
                note.octave = jsOr(value / 12.0, 0)
                note.tone = value - note.octave * 12.0
            }
        }
        let track: Track = staff.track
        let trackInfo: TrackInfo = self._indexToTrackInfo.get(track.index)!
        if !isPitched {
            note.percussionArticulation = trackInfo.getOrCreateArticulation(instrumentId ?? "", note)
            return
        }
        if instrumentId != nil && trackInfo.isUnpitchedInstrument(instrumentId!) {
            note.percussionArticulation = trackInfo.getOrCreateArticulation(instrumentId!, note)
        } else if staff.isPercussion {
            let knownArticulation: InstrumentArticulation? = PercussionMapper.getArticulationById(note.displayValue)
            if TypeHelper.isTruthy(knownArticulation) {
                note.percussionArticulation = track.getOrRegisterPercussionArticulation(knownArticulation!)
            }
        }
    }

    private func _parsePlay(_ element: XmlNode, _ note: Note?) {
        for c in element.childElements() {
            switch c.localName! {
            case "mute":
                if TypeHelper.isTruthy(note) {
                    switch c.innerText {
                    case "palm":
                        note!.isPalmMute = true
                    case "on", "straight":
                        if self._isFrettedInstrumentNote(note!) {
                            note!.isDead = true
                        }
                    default:
                        break
                    }
                }
            case "semi-pitched":
                break
            default:
                break
            }
        }
    }

    private static let _b4Value: Double = 71.0

    private func _estimateBeamDirection(_ writtenNoteValue: Double) -> BeamDirection {
        return writtenNoteValue < MusicXmlImporter._b4Value ? BeamDirection.Down : BeamDirection.Up
    }

    private func _parseNoteHead(_ element: XmlNode, _ note: Note, _ beatDuration: Duration, _ beamDirection: BeamDirection) {
        if element.getAttribute("parentheses", "no") == "yes" {
            note.isGhost = true
        }
        let filled: String = element.getAttribute("filled", "")
        var forceFill: Bool? = nil
        if filled == "yes" {
            forceFill = true
        } else if filled == "no" {
            forceFill = false
        }
        note.style = NoteStyle()
        switch element.innerText {
        case "arrow down":
            note.style!.noteHeadCenterOnStem = true
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadTriangleDownDoubleWhole, MusicFontSymbol.NoteheadTriangleDownWhole, MusicFontSymbol.NoteheadTriangleDownHalf, MusicFontSymbol.NoteheadTriangleDownBlack)
        case "arrow up":
            note.style!.noteHeadCenterOnStem = true
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadTriangleUpDoubleWhole, MusicFontSymbol.NoteheadTriangleUpWhole, MusicFontSymbol.NoteheadTriangleUpHalf, MusicFontSymbol.NoteheadTriangleUpBlack)
        case "back slashed":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadSlashedDoubleWhole2, MusicFontSymbol.NoteheadSlashedWhole2, MusicFontSymbol.NoteheadSlashedHalf2, MusicFontSymbol.NoteheadSlashedBlack2)
        case "circle dot":
            note.style!.noteHead = MusicFontSymbol.NoteheadRoundWhiteWithDot
        case "circle-x":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadCircleXDoubleWhole, MusicFontSymbol.NoteheadCircleXWhole, MusicFontSymbol.NoteheadCircleXHalf, MusicFontSymbol.NoteheadCircleX)
        case "circled":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadCircledDoubleWhole, MusicFontSymbol.NoteheadCircledWhole, MusicFontSymbol.NoteheadCircledHalf, MusicFontSymbol.NoteheadCircledBlack)
        case "cluster":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadClusterDoubleWhole3rd, MusicFontSymbol.NoteheadClusterWhole3rd, MusicFontSymbol.NoteheadClusterHalf3rd, MusicFontSymbol.NoteheadClusterQuarter3rd)
        case "cross":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadPlusDoubleWhole, MusicFontSymbol.NoteheadPlusWhole, MusicFontSymbol.NoteheadPlusHalf, MusicFontSymbol.NoteheadPlusBlack)
        case "diamond":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadDiamondDoubleWhole, MusicFontSymbol.NoteheadDiamondWhole, MusicFontSymbol.NoteheadDiamondHalf, MusicFontSymbol.NoteheadDiamondBlack)
        case "do":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteShapeTriangleUpWhite, MusicFontSymbol.NoteShapeTriangleUpWhite, MusicFontSymbol.NoteShapeTriangleUpWhite, MusicFontSymbol.NoteShapeTriangleUpBlack)
        case "fa":
            if beamDirection == BeamDirection.Up {
                self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteShapeTriangleRightWhite, MusicFontSymbol.NoteShapeTriangleRightWhite, MusicFontSymbol.NoteShapeTriangleRightWhite, MusicFontSymbol.NoteShapeTriangleRightBlack)
            } else {
                self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteShapeTriangleLeftWhite, MusicFontSymbol.NoteShapeTriangleLeftWhite, MusicFontSymbol.NoteShapeTriangleLeftWhite, MusicFontSymbol.NoteShapeTriangleLeftBlack)
            }
        case "fa up":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteShapeTriangleLeftWhite, MusicFontSymbol.NoteShapeTriangleLeftWhite, MusicFontSymbol.NoteShapeTriangleLeftWhite, MusicFontSymbol.NoteShapeTriangleLeftBlack)
        case "inverted triangle":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadTriangleDownDoubleWhole, MusicFontSymbol.NoteheadTriangleDownWhole, MusicFontSymbol.NoteheadTriangleDownHalf, MusicFontSymbol.NoteheadTriangleDownBlack)
        case "la":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteShapeSquareWhite, MusicFontSymbol.NoteShapeSquareWhite, MusicFontSymbol.NoteShapeSquareWhite, MusicFontSymbol.NoteShapeSquareBlack)
        case "left triangle":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadTriangleRightWhite, MusicFontSymbol.NoteheadTriangleRightWhite, MusicFontSymbol.NoteheadTriangleRightWhite, MusicFontSymbol.NoteheadTriangleRightBlack)
        case "mi":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteShapeDiamondWhite, MusicFontSymbol.NoteShapeDiamondWhite, MusicFontSymbol.NoteShapeDiamondWhite, MusicFontSymbol.NoteShapeDiamondBlack)
        case "none":
            note.style!.noteHead = MusicFontSymbol.NoteheadNull
        case "normal":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadDoubleWhole, MusicFontSymbol.NoteheadWhole, MusicFontSymbol.NoteheadHalf, MusicFontSymbol.NoteheadBlack)
        case "re":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteShapeMoonWhite, MusicFontSymbol.NoteShapeMoonWhite, MusicFontSymbol.NoteShapeMoonWhite, MusicFontSymbol.NoteShapeMoonBlack)
        case "rectangle":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadSquareWhite, MusicFontSymbol.NoteheadSquareWhite, MusicFontSymbol.NoteheadSquareWhite, MusicFontSymbol.NoteheadSquareBlack)
        case "slash":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadSlashWhiteWhole, MusicFontSymbol.NoteheadSlashWhiteWhole, MusicFontSymbol.NoteheadSlashWhiteHalf, MusicFontSymbol.NoteheadSlashHorizontalEnds)
        case "slashed":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadSlashedDoubleWhole1, MusicFontSymbol.NoteheadSlashedWhole1, MusicFontSymbol.NoteheadSlashedHalf1, MusicFontSymbol.NoteheadSlashedBlack1)
        case "so":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteShapeRoundWhite, MusicFontSymbol.NoteShapeRoundWhite, MusicFontSymbol.NoteShapeRoundWhite, MusicFontSymbol.NoteShapeRoundBlack)
        case "square":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteShapeSquareWhite, MusicFontSymbol.NoteShapeSquareWhite, MusicFontSymbol.NoteShapeSquareWhite, MusicFontSymbol.NoteShapeSquareBlack)
        case "ti":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteShapeTriangleRoundWhite, MusicFontSymbol.NoteShapeTriangleRoundWhite, MusicFontSymbol.NoteShapeTriangleRoundWhite, MusicFontSymbol.NoteShapeTriangleRoundBlack)
        case "triangle":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadTriangleUpDoubleWhole, MusicFontSymbol.NoteheadTriangleUpWhole, MusicFontSymbol.NoteheadTriangleUpHalf, MusicFontSymbol.NoteheadTriangleUpBlack)
        case "x":
            self._applyNoteHead(note, beatDuration, forceFill, MusicFontSymbol.NoteheadXDoubleWhole, MusicFontSymbol.NoteheadXWhole, MusicFontSymbol.NoteheadXHalf, MusicFontSymbol.NoteheadXBlack)
            if self._isFrettedInstrumentNote(note) {
                note.isDead = true
            }
        default:
            break
        }
    }

    private func _createRestForGap(_ gap: Double, _ preferredDuration: Duration) -> Beat? {
        var parampreferredDuration = preferredDuration
        var preferredDurationTicks: Double = MidiUtils.toTicks(parampreferredDuration)
        while preferredDurationTicks > gap {
            if parampreferredDuration == Duration.TwoHundredFiftySixth {
                return nil
            }
            parampreferredDuration = Duration.fromValue((Double((parampreferredDuration).rawValue) * 2.0))
            preferredDurationTicks = MidiUtils.toTicks(parampreferredDuration)
        }
        let placeholder: Beat = Beat()
        placeholder.dynamics = self._currentDynamics
        placeholder.isEmpty = false
        placeholder.duration = parampreferredDuration
        placeholder.overrideDisplayDuration = preferredDurationTicks
        placeholder.updateDurations()
        return placeholder
    }

    private func _insertBeatToVoice(_ newBeat: Beat, _ voice: Voice) {
        if voice.beats.length > 0 {
            let lastBeat: Beat = voice.beats[(voice.beats.length - 1.0).toInt()]
            lastBeat.nextBeat = newBeat
            newBeat.previousBeat = lastBeat
            var previousNonGraceBeat: Beat? = lastBeat
            while previousNonGraceBeat != nil {
                if previousNonGraceBeat!.graceType == GraceType.None {
                    break
                }
                if previousNonGraceBeat!.index > 0 {
                    previousNonGraceBeat = previousNonGraceBeat!.previousBeat
                } else {
                    previousNonGraceBeat = nil
                }
            }
            if previousNonGraceBeat != nil {
                newBeat.displayStart = previousNonGraceBeat!.displayEnd
            }
        }
        voice.addBeat(newBeat)
    }

    private func _musicXmlDivisionsToAlphaTabTicks(_ divisions: Double) -> Double {
        return (divisions * MidiUtils.QuarterTime) / self._divisionsPerQuarterNote
    }

    private func _parseBeatDuration(_ element: XmlNode) -> Duration? {
        switch element.innerText {
        case "1024th":
            return Duration.TwoHundredFiftySixth
        case "512th":
            return Duration.TwoHundredFiftySixth
        case "256th":
            return Duration.TwoHundredFiftySixth
        case "128th":
            return Duration.OneHundredTwentyEighth
        case "64th":
            return Duration.SixtyFourth
        case "32nd":
            return Duration.ThirtySecond
        case "16th":
            return Duration.Sixteenth
        case "eighth":
            return Duration.Eighth
        case "quarter":
            return Duration.Quarter
        case "half":
            return Duration.Half
        case "whole":
            return Duration.Whole
        case "breve":
            return Duration.DoubleWhole
        case "long":
            return Duration.QuadrupleWhole
        default:
            break
        }
        return nil
    }

    nonisolated(unsafe) private static var _allDurations: List<Duration> = List<Duration>(Duration.TwoHundredFiftySixth, Duration.OneHundredTwentyEighth, Duration.SixtyFourth, Duration.ThirtySecond, Duration.Sixteenth, Duration.Eighth, Duration.Quarter, Duration.Half, Duration.Whole, Duration.DoubleWhole, Duration.QuadrupleWhole)

    nonisolated(unsafe) private static var _allDurationTicks: List<Double> = MusicXmlImporter._allDurations.map({ (d: Duration) -> Double in
        return MidiUtils.toTicks(d)
    })

    private func _applyBeatDurationFromTicks(_ newBeat: Beat, _ ticks: Double, _ beatDuration: Duration?, _ applyDisplayDuration: Bool) {
        var parambeatDuration = beatDuration
        if !TypeHelper.isTruthy(parambeatDuration) {
            do {
                var i: Double = 0.0
                while i < MusicXmlImporter._allDurations.length {
                    let dt: Double = MusicXmlImporter._allDurationTicks[(i).toInt()]
                    if ticks >= dt {
                        parambeatDuration = MusicXmlImporter._allDurations[(i).toInt()]
                    } else {
                        break
                    }
                    i += 1
                }
            }
        }
        newBeat.duration = parambeatDuration ?? Duration.Sixteenth
        if applyDisplayDuration {
            newBeat.overrideDisplayDuration = ticks
        }
        newBeat.updateDurations()
    }

    private func _parseLyric(_ element: XmlNode, _ beat: Beat, _ track: Track) {
        let info: TrackInfo = self._indexToTrackInfo.get(track.index)!
        let index: Double = info.getLyricLine(element.getAttribute("number", ""))
        if beat.lyrics == nil {
            beat.lyrics = List<String>()
        }
        while beat.lyrics!.length <= index {
            beat.lyrics!.push("")
        }
        for c in element.childElements() {
            switch c.localName! {
            case "text":
                if TypeHelper.isTruthy(beat.lyrics![(index).toInt()]) {
                    beat.lyrics![(index).toInt()] += " \((c.innerText).toTemplate())"
                } else {
                    beat.lyrics![(index).toInt()] = c.innerText
                }
            case "elision":
                beat.lyrics![(index).toInt()] += c.innerText
            default:
                break
            }
        }
    }

    private func _parseNotations(_ element: XmlNode, _ note: Note?, _ beat: Beat, _ voice: String) {
        for c in element.childElements() {
            switch c.localName! {
            case "tied":
                if TypeHelper.isTruthy(note) {
                    self._parseTied(c, note!, voice)
                }
            case "slur":
                if TypeHelper.isTruthy(note) {
                    self._parseNoteLink(c, MusicXmlNoteLinkType.Slur, note!, voice)
                }
            case "glissando":
                if TypeHelper.isTruthy(note) {
                    self._parseNoteLink(c, MusicXmlNoteLinkType.Glissando, note!, voice)
                }
            case "slide":
                if TypeHelper.isTruthy(note) {
                    self._parseNoteLink(c, MusicXmlNoteLinkType.Slide, note!, voice)
                }
            case "ornaments":
                if TypeHelper.isTruthy(note) {
                    self._parseOrnaments(c, note!, voice)
                }
            case "technical":
                self._parseTechnical(c, note, beat)
            case "articulations":
                if TypeHelper.isTruthy(note) {
                    self._parseArticulations(c, note!)
                }
            case "dynamics":
                let dynamics: DynamicValue? = self._parseDynamics(c)
                if dynamics != nil {
                    beat.dynamics = (dynamics as! DynamicValue)
                    self._currentDynamics = (dynamics as! DynamicValue)
                }
            case "fermata":
                self._parseFermata(c, beat)
            case "arpeggiate":
                self._parseArpeggiate(c, beat)
            default:
                break
            }
        }
    }

    private func _noteLinks(_ note: Note) -> MusicXmlNoteLinks {
        return self._indexToTrackInfo.get(note.beat.voice.bar.staff.track.index)!.noteLinks
    }

    /**
     * Reads an element linking notes (e.g. `<slur>`, `<slide>`) identified by its number.
     */
    private func _parseNoteLink(_ element: XmlNode, _ type: MusicXmlNoteLinkType, _ note: Note, _ voice: String) {
        let number: String = element.getAttribute("number", "1")
        switch element.getAttribute("type") {
        case "start":
            self._noteLinks(note).start(type, number, note, voice, 0.0)
        case "stop":
            self._noteLinks(note).stop(type, number, note, voice)
        default:
            break
        }
    }

    private func _getStaffContext(_ staff: Staff) -> StaffContext {
        if !self._staffToContext.has(staff) {
            let context: StaffContext = StaffContext()
            self._staffToContext.set(staff, context)
            return context
        }
        return self._staffToContext.get(staff)!
    }

    private func _parseArpeggiate(_ element: XmlNode, _ beat: Beat) {
        let direction: String = element.getAttribute("direction", "down")
        switch direction {
        case "down":
            beat.brushType = BrushType.ArpeggioDown
        case "up":
            beat.brushType = BrushType.ArpeggioUp
        default:
            break
        }
    }

    private func _parseFermata(_ element: XmlNode, _ beat: Beat) {
        var fermata: FermataType
        switch element.innerText {
        case "normal":
            fermata = FermataType.Medium
        case "angled":
            fermata = FermataType.Short
        case "square":
            fermata = FermataType.Long
        default:
            fermata = FermataType.Medium
        }
        beat.fermata = Fermata()
        beat.fermata!.type = fermata
    }

    private func _parseArticulations(_ element: XmlNode, _ note: Note) {
        for c in element.childElements() {
            switch c.localName! {
            case "accent":
                note.accentuated = AccentuationType.Normal
            case "strong-accent":
                note.accentuated = AccentuationType.Heavy
            case "staccato":
                note.isStaccato = true
            case "tenuto":
                note.accentuated = AccentuationType.Tenuto
            default:
                break
            }
        }
    }

    private func _parseTechnical(_ element: XmlNode, _ note: Note?, _ beat: Beat) {
        let bends: List<XmlNode> = List<XmlNode>()
        for c in element.childElements() {
            switch c.localName! {
            case "up-bow":
                beat.pickStroke = PickStroke.Up
            case "down-bow":
                beat.pickStroke = PickStroke.Down
            case "fingering":
                if TypeHelper.isTruthy(note) {
                    note!.leftHandFinger = self._parseFingering(c, !GeneralMidi.isPiano(beat.voice.bar.staff.track.playbackInfo.program))
                }
            case "pluck":
                if TypeHelper.isTruthy(note) {
                    note!.rightHandFinger = self._parseFingering(c, false)
                }
            case "fret":
                if TypeHelper.isTruthy(note) {
                    if beat.voice.bar.staff.tuning.length > 0 {
                        note!.fret = Number.parseInt(c.innerText, 10.0)
                    } else {
                        Logger.warning("MusicXML", "Ignoring <fret> on staff without tuning")
                    }
                }
            case "string":
                if TypeHelper.isTruthy(note) {
                    note!.string = Note.getStringCount(beat.voice.bar.staff) - Number.parseInt(c.innerText, 10.0) + 1.0
                }
            case "hammer-on", "pull-off":
                if TypeHelper.isTruthy(TypeHelper.isTruthy(note) && c.getAttribute("type", "start") == "start") {
                    note!.isHammerPullOrigin = true
                }
            case "bend":
                bends.push(c)
            case "tap":
                beat.tap = true
            case "smear":
                if TypeHelper.isTruthy(note) {
                    note!.vibrato = VibratoType.Slight
                }
            case "golpe":
                switch c.getAttribute("placement", "above") {
                case "above":
                    beat.golpe = GolpeType.Finger
                case "below":
                    beat.golpe = GolpeType.Thumb
                default:
                    break
                }
            default:
                break
            }
        }
        if TypeHelper.isTruthy(TypeHelper.isTruthy(note) && bends.length > 0) {
            self._parseBends(bends, note!)
        }
    }

    private func _parseBends(_ elements: List<XmlNode>, _ note: Note) {
        let baseOffset: Double = BendPoint.MaxPosition / elements.length
        var currentValue: Double = 0.0
        var currentOffset: Double = 0.0
        var isFirstBend: Bool = true
        for bend in elements {
            let bendAlterElement: XmlNode? = bend.findChildElement("bend-alter")
            if TypeHelper.isTruthy(bendAlterElement) {
                let absValue: Double = Math.round(Math.abs(Number.parseFloat(bendAlterElement!.innerText)) * 2.0)
                if TypeHelper.isTruthy(bend.findChildElement("pre-bend")) {
                    if isFirstBend {
                        currentValue += absValue
                        note.addBendPoint(BendPoint(currentOffset, currentValue))
                        currentOffset += baseOffset
                        note.addBendPoint(BendPoint(currentOffset, currentValue))
                        isFirstBend = false
                    } else {
                        currentOffset += baseOffset
                    }
                } else if TypeHelper.isTruthy(bend.findChildElement("release")) {
                    if isFirstBend {
                        currentValue += absValue
                    }
                    note.addBendPoint(BendPoint(currentOffset, currentValue))
                    currentOffset += baseOffset
                    currentValue -= absValue
                    note.addBendPoint(BendPoint(currentOffset, currentValue))
                    isFirstBend = false
                } else {
                    note.addBendPoint(BendPoint(currentOffset, currentValue))
                    currentValue += absValue
                    currentOffset += baseOffset
                    note.addBendPoint(BendPoint(currentOffset, currentValue))
                    isFirstBend = false
                }
            }
        }
    }

    /**
     * Parses the text of a `<fingering>` or `<pluck>` element into a finger.
     */
    private func _parseFingering(_ c: XmlNode, _ fretNumbering: Bool) -> Fingers {
        switch c.innerText.lowercase() {
        case "0":
            return Fingers.NoOrDead
        case "1":
            return fretNumbering ? Fingers.IndexFinger : Fingers.Thumb
        case "2":
            return fretNumbering ? Fingers.MiddleFinger : Fingers.IndexFinger
        case "3":
            return fretNumbering ? Fingers.AnnularFinger : Fingers.MiddleFinger
        case "4":
            return fretNumbering ? Fingers.LittleFinger : Fingers.AnnularFinger
        case "5":
            return fretNumbering ? Fingers.Thumb : Fingers.LittleFinger
        case "p", "t":
            return Fingers.Thumb
        case "i":
            return Fingers.IndexFinger
        case "m":
            return Fingers.MiddleFinger
        case "a":
            return Fingers.AnnularFinger
        case "c", "e", "o", "q", "s", "x":
            return Fingers.LittleFinger
        default:
            break
        }
        return Fingers.Unknown
    }

    private func _parseOrnaments(_ element: XmlNode, _ note: Note, _ voice: String) {
        var trillStep: Double = -1.0
        for c in element.childElements() {
            if c.localName == "trill-mark" {
                switch c.getAttribute("trill-step", "whole") {
                case "half":
                    trillStep = 1.0
                case "unison":
                    trillStep = 0.0
                default:
                    trillStep = 2.0
                }
            }
        }
        let links: MusicXmlNoteLinks = self._noteLinks(note)
        var hasLine: Bool = false
        for c in element.childElements() {
            switch c.localName! {
            case "turn":
                note.ornament = NoteOrnament.Turn
            case "inverted-turn":
                note.ornament = NoteOrnament.InvertedTurn
            case "wavy-line":
                let number: String = c.getAttribute("number", "1")
                switch c.getAttribute("type") {
                case "start":
                    links.start(MusicXmlNoteLinkType.WavyLine, number, note, voice, trillStep)
                    hasLine = true
                case "continue":
                    links.`continue`(MusicXmlNoteLinkType.WavyLine, number, note, voice, trillStep)
                    hasLine = true
                case "stop":
                    links.stop(MusicXmlNoteLinkType.WavyLine, number, note, voice)
                default:
                    break
                }
            case "mordent":
                note.ornament = NoteOrnament.LowerMordent
            case "inverted-mordent":
                note.ornament = NoteOrnament.UpperMordent
            case "tremolo":
                let tremolo: TremoloPickingEffect = TremoloPickingEffect()
                note.beat.tremoloPicking = tremolo
                tremolo.marks = Number.parseInt(c.innerText, 10.0)
                if (c.getAttribute("type", "") == "unmeasured" && tremolo.marks == 0.0) || c.getAttribute("smufl", "") == "buzzRoll" {
                    tremolo.style = TremoloPickingStyle.BuzzRoll
                }
            default:
                break
            }
        }
        if trillStep >= 0 && !hasLine {
            links.single(MusicXmlNoteLinkType.WavyLine, note, trillStep)
        }
    }

    private func _parseTied(_ element: XmlNode, _ note: Note, _ voice: String) {
        let pitch: String = "\((self._calculatePitchedNoteValue(note)).toTemplate())"
        switch element.getAttribute("type") {
        case "start":
            self._noteLinks(note).start(MusicXmlNoteLinkType.Tie, pitch, note, voice, 0.0)
        case "stop":
            self._noteLinks(note).stop(MusicXmlNoteLinkType.Tie, pitch, note, voice)
        case "let-ring":
            note.isLetRing = true
        default:
            break
        }
    }

    private func _parseStem(_ element: XmlNode) -> BeamDirection? {
        switch element.innerText {
        case "down":
            return BeamDirection.Down
        case "up":
            return BeamDirection.Up
        default:
            return nil
        }
    }

    /**
     * The spelling of the note is defined by its `<pitch>`, the `<accidental>` only describes the printed sign
     * which is computed during rendering. We only report signs which contradict the pitch.
     * https://www.w3.org/2021/06/musicxml40/musicxml-reference/elements/accidental/
     */
    private func _parseAccidental(_ element: XmlNode, _ note: Note) {
        var accidentalMode: NoteAccidentalMode = NoteAccidentalMode.Default
        switch element.innerText {
        case "sharp":
            accidentalMode = NoteAccidentalMode.ForceSharp
        case "natural":
            accidentalMode = NoteAccidentalMode.ForceNatural
        case "flat":
            accidentalMode = NoteAccidentalMode.ForceFlat
        case "double-sharp":
            accidentalMode = NoteAccidentalMode.ForceDoubleSharp
        case "flat-flat":
            accidentalMode = NoteAccidentalMode.ForceDoubleFlat
        default:
            break
        }
        if accidentalMode != NoteAccidentalMode.Default && note.accidentalMode != NoteAccidentalMode.Default && accidentalMode != note.accidentalMode {
            Logger.warning("MusicXML", "Accidental '\((element.innerText).toTemplate())' does not match the pitch of the note, the pitch is used")
        }
    }

    private func _calculatePitchedNoteValue(_ note: Note) -> Double {
        return note.octave * 12.0 + note.tone
    }

    private func _parseDuration(_ element: XmlNode) -> Double {
        return self._musicXmlDivisionsToAlphaTabTicks(Number.parseFloat(element.innerText))
    }

    private func _parseUnpitched(_ element: XmlNode, _ _track: Track) -> Note {
        var step: String = ""
        var octave: Double = 0.0
        for c in element.childElements() {
            switch c.localName! {
            case "display-step":
                step = c.innerText
            case "display-octave":
                octave = Number.parseInt(c.innerText, 10.0) + 1.0
            default:
                break
            }
        }
        let note: Note = Note()
        if step == "" {
            note.octave = 0.0
            note.tone = 0.0
        } else {
            let value: Double = octave * 12.0 + (ModelUtils.getToneForText(step)?.noteValue ?? 0.0)
            note.octave = jsOr(value / 12.0, 0)
            note.tone = value - note.octave * 12.0
        }
        return note
    }

    private func _parsePitch(_ element: XmlNode) -> Note {
        var step: String = ""
        var semitones: Double = 0.0
        var octave: Double = 0.0
        for c in element.childElements() {
            switch c.localName! {
            case "step":
                step = c.innerText
            case "alter":
                semitones = Number.parseFloat(c.innerText)
                if Number.isNaN(semitones) {
                    semitones = 0.0
                }
            case "octave":
                octave = Number.parseInt(c.innerText, 10.0) + 1.0
            default:
                break
            }
        }
        semitones = jsOr(semitones, 0)
        let value: Double = octave * 12.0 + (ModelUtils.getToneForText(step)?.noteValue ?? 0.0) + semitones
        let note: Note = Note()
        note.octave = jsOr(value / 12.0, 0)
        note.tone = value - note.octave * 12.0
        note.accidentalMode = MusicXmlImporter._accidentalModeForAlter(semitones)
        return note
    }

    /**
     * The `<step>` and `<alter>` define the spelling of the note (e.g. F# vs Gb), also if no `<accidental>` is printed.
     * https://www.w3.org/2021/06/musicxml40/musicxml-reference/elements/pitch/
     */
    private static func _accidentalModeForAlter(_ alter: Double) -> NoteAccidentalMode {
        if alter == 0.0 {
            return NoteAccidentalMode.ForceNatural
        }
        if alter == 1.0 {
            return NoteAccidentalMode.ForceSharp
        }
        if alter == 2.0 {
            return NoteAccidentalMode.ForceDoubleSharp
        }
        if alter == -1.0 {
            return NoteAccidentalMode.ForceFlat
        }
        if alter == -2.0 {
            return NoteAccidentalMode.ForceDoubleFlat
        }
        return NoteAccidentalMode.Default
    }

    private func _applyNoteHead(_ note: Note, _ beatDuration: Duration, _ forceFill: Bool?, _ doubleWhole: MusicFontSymbol, _ whole: MusicFontSymbol, _ half: MusicFontSymbol, _ filled: MusicFontSymbol) {
        if forceFill == nil {
            switch beatDuration {
            case Duration.QuadrupleWhole, Duration.DoubleWhole:
                note.style!.noteHead = doubleWhole
            case Duration.Whole:
                note.style!.noteHead = whole
            case Duration.Half:
                note.style!.noteHead = half
            default:
                note.style!.noteHead = filled
            }
        } else if forceFill! == true {
            note.style!.noteHead = filled
        } else {
            switch beatDuration {
            case Duration.QuadrupleWhole, Duration.DoubleWhole:
                note.style!.noteHead = doubleWhole
            case Duration.Whole:
                note.style!.noteHead = whole
            case Duration.Half:
                note.style!.noteHead = half
            default:
                note.style!.noteHead = half
            }
        }
    }

    public override init() {
        super.init()
    }
}

/**
 * The pitch a note of a MusicXML harmonic describes.
 */
internal enum MusicXmlHarmonicPitch: Int, IAlphaTabEnum, CaseIterable {
    case None = 0
    case Base = 1
    case Touching = 2
    case Sounding = 3
}

internal final class MusicXmlHarmonic: IRecord {
    public var type: HarmonicType

    public var pitch: MusicXmlHarmonicPitch

    /**
     * Groups the notes of one harmonic when a chord holds several of them (number-level, MusicXML 4.1).
     */
    public var group: String

    public init(type: HarmonicType, pitch: MusicXmlHarmonicPitch, group: String) {
        self.type = type
        self.pitch = pitch
        self.group = group
    }
}

/**
 * The note which represents a MusicXML harmonic in the current beat.
 */
internal final class MusicXmlHarmonicGroup: IRecord {
    public var note: Note

    public var type: HarmonicType

    public var isBasePitch: Bool = false

    public var hasTouchingPitch: Bool = false

    public init(note: Note, type: HarmonicType, isBasePitch: Bool, hasTouchingPitch: Bool) {
        self.note = note
        self.type = type
        self.isBasePitch = isBasePitch
        self.hasTouchingPitch = hasTouchingPitch
    }
}

internal final class StaffContext {
    public var currentDynamics: DynamicValue = DynamicValue.F

    public var transpose: Double = 0.0

    public var isExplicitlyBeamed: Bool = false

    public init() {}
}

internal final class InstrumentArticulationWithPlaybackInfo: InstrumentArticulation {
    /**
     * The midi channel number to use when playing the note (-1 if using the default track channels).
     */
    public var outputMidiChannel: Double = -1.0

    /**
     * The midi channel program to use when playing the note (-1 if using the default track program).
     */
    public var outputMidiProgram: Double = -1.0

    /**
     * The midi bank to use when playing the note (-1 if using the default track bank).
     */
    public var outputMidiBank: Double = -1.0

    /**
     * The volume to use when playing the note (-1 if using the default track volume).
     */
    public var outputVolume: Double = -1.0

    /**
     * The balance to use when playing the note (-1 if using the default track balance).
     */
    public var outputBalance: Double = -1.0

    /**
     * Whether this instrument was declared as an unpitched/percussion sound via `<midi-unpitched>`.
     */
    public var isUnpitched: Bool = false

    public override init(_ elementType: String = "", _ staffLine: Double = 0.0, _ outputMidiNumber: Double = 0.0, _ noteHeadDefault: MusicFontSymbol = MusicFontSymbol.None, _ noteHeadHalf: MusicFontSymbol = MusicFontSymbol.None, _ noteHeadWhole: MusicFontSymbol = MusicFontSymbol.None, _ techniqueSymbol: MusicFontSymbol = MusicFontSymbol.None, _ techniqueSymbolPlacement: TechniqueSymbolPlacement = TechniqueSymbolPlacement.Inside, _ id: Double = 0.0) {
        super.init(elementType, 
        staffLine, 
        outputMidiNumber, 
        noteHeadDefault, 
        noteHeadHalf, 
        noteHeadWhole, 
        techniqueSymbol, 
        techniqueSymbolPlacement, 
        id)
    }
}

internal final class TrackInfo {
    public var track: Track!

    public var firstArticulation: InstrumentArticulationWithPlaybackInfo? = nil

    public var instruments: Map<String, InstrumentArticulationWithPlaybackInfo> = Map<String, InstrumentArticulationWithPlaybackInfo>()

    private var _instrumentIdToArticulationIndex: Map<String, Double> = Map<String, Double>()

    /**
     * The spans of directions and measure styles (e.g. let ring), span numbers are unique within a part.
     */
    public var spans: MusicXmlSpanTracker = MusicXmlSpanTracker()

    public var noteLinks: MusicXmlNoteLinks = MusicXmlNoteLinks()

    /**
     * The alternate endings started but not stopped yet.
     */
    public var openEndings: Double = 0.0

    private var _lyricsLine: Double = 0.0

    private var _lyricsLines: Map<String, Double> = Map<String, Double>()

    public init(_ track: Track) {
        self.track = track
    }

    public func getLyricLine(_ number: String) -> Double {
        if self._lyricsLines.has(number) {
            return self._lyricsLines.get(number)!
        }
        let line: Double = self._lyricsLine
        self._lyricsLines.set(number, line)
        self._lyricsLine += 1
        return line
    }

    nonisolated(unsafe) private static var _defaultNoteArticulation: InstrumentArticulation = InstrumentArticulation.create(0.0, "Default", 0.0, 0.0, MusicFontSymbol.NoteheadBlack, MusicFontSymbol.NoteheadHalf, MusicFontSymbol.NoteheadWhole)

    public func getOrCreateArticulation(_ instrumentId: String, _ note: Note) -> Double {
        let noteValue: Double = note.octave * 12.0 + note.tone
        let lookup: String = "\((instrumentId).toTemplate())_\((noteValue).toTemplate())"
        if self._instrumentIdToArticulationIndex.has(lookup) {
            return self._instrumentIdToArticulationIndex.get(lookup)!
        }
        var articulation: InstrumentArticulation
        if self.instruments.has(instrumentId) {
            articulation = self.instruments.get(instrumentId)!
        } else {
            articulation = TrackInfo._defaultNoteArticulation
        }
        let index: Double = self.track.percussionArticulations.length
        let bar: Bar = note.beat.voice.bar
        var musicXmlStaffSteps: Double
        if noteValue == 0.0 {
            musicXmlStaffSteps = 4.0
        } else {
            let spelling: ResolvedSpelling = ModelUtils.resolveSpelling(bar.keySignature, noteValue, NoteAccidentalMode.Default)
            musicXmlStaffSteps = AccidentalHelper.calculateNoteSteps(bar.clef, spelling)
        }
        let actualSteps: Double = note.beat.voice.bar.staff.standardNotationLineCount * 2.0 - 1.0
        let fiveLineSteps: Double = 5.0 * 2.0 - 1.0
        let stepDifference: Double = fiveLineSteps - actualSteps
        let staffLine: Double = musicXmlStaffSteps - stepDifference
        let newArticulation: InstrumentArticulation = InstrumentArticulation.create(articulation.id, articulation.elementType, staffLine, articulation.outputMidiNumber, articulation.noteHeadDefault, articulation.noteHeadHalf, articulation.noteHeadWhole, articulation.techniqueSymbol, articulation.techniqueSymbolPlacement)
        self._instrumentIdToArticulationIndex.set(lookup, index)
        self.track.percussionArticulations.push(newArticulation)
        return index
    }

    public func isUnpitchedInstrument(_ instrumentId: String) -> Bool {
        return self.instruments.has(instrumentId) && self.instruments.get(instrumentId)!.isUnpitched
    }
}

/**
 * Tracks how raw MusicXML voice numbers on a staff map into alphaTab's local
 * (dense, 0-based) voice slots. Collapses MuseScore's sparse `staff*4+local`
 * convention (staff 2 → voices 5..8) into dense per-staff indices.
 */
internal final class StaffVoicePacking {
    public var mapping: Map<String, Double> = Map<String, Double>()

    public var sortedRawVoices: List<String> = List<String>()

    public init() {}
}
